 mesh=len(d['meshes']);d['meshes'].append({'name':'SceneOnlySteppedPreparationBench','primitives':primitives});node=len(d['nodes']);d['nodes'].append({'name':'SCENE_ONLY__SteppedPreparationBench','mesh':mesh,'extras':{'new_independent_model':False}});d['nodes'][0]['children'].append(node);d['buffers']=[{'byteLength':len(blob)}]
